import pandas as pd
import numpy as np
from statsmodels.tsa.filters.hp_filter import hpfilter
import re

def get_data(file, col):
    df = pd.read_excel(file, engine='xlrd')
    ann, qtr, cur_y = {}, {}, None
    for i in range(len(df)):
        lbl = str(df.iloc[i, 0]).strip()
        val = df.iloc[i, col]
        m = re.search(r'(\d{4})', lbl)
        if m:
            y = int(m.group(1))
            if ':' in lbl:
                cur_y = y
                try: qtr.setdefault(y, []).append(float(val))
                except: pass
            elif lbl.endswith('.') or (len(lbl) == 4 and lbl.isdigit()):
                try: ann[y] = float(val)
                except: pass
        elif lbl in ['I.', 'II.', 'III.', 'IV.', 'I p.', 'II p.', 'III p.', 'IV p.', 'II', 'III', 'IV']:
            if cur_y is not None:
                try: qtr.setdefault(cur_y, []).append(float(val))
                except: pass
    res = {}
    for y in range(1973, 2025):
        if y == 2024 and y in qtr: res[y] = np.mean(qtr[y])
        elif y in ann: res[y] = ann[y]
        elif y in qtr: res[y] = np.mean(qtr[y])
    return pd.Series(res)

pce = get_data('ERP-2025-table10.xls', 1)
pfi = get_data('ERP-2025-table12.xls', 1)
cpi = pd.read_excel('CPI.xlsx').set_index('Year')['CPI_2024']

years = range(1973, 2025)
data = pd.DataFrame({'pce': pce, 'pfi': pfi, 'cpi': cpi}).reindex(years)

log_rpce = np.log(data['pce'] / data['cpi'])
log_rpfi = np.log(data['pfi'] / data['cpi'])

cyc_pce, _ = hpfilter(log_rpce, lamb=100)
cyc_pfi, _ = hpfilter(log_rpfi, lamb=100)

corr = cyc_pce.corr(cyc_pfi)
print(f'{corr:.5f}')
with open('answer.txt', 'w') as f: f.write(f'{corr:.5f}\n')
